        const [weeklyState,setWeeklyState]=useState(null);
        const [lineup,setLineup]=useState([]),[favorId,setFavorId]=useState('kratos-1'),[target,setTarget]=useState(''),[sourceWeek,setSourceWeek]=useState(1),[removeId,setRemoveId]=useState(null);
        const [invite,setInvite]=useState(()=>{const code=new URLSearchParams(window.location.search).get('duat_invite');try{if(code)sessionStorage.setItem('duat-pending-invite',code);return code||sessionStorage.getItem('duat-pending-invite')||'';}catch{return code||'';}});
        const activeRef=useRef(null),requestRef=useRef(0),fileRef=useRef(null),campaignRef=useRef(null);campaignRef.current=campaign;
