        const acceptRoom=(next,opening=false)=>{if(!next)return;const previous=activeRef.current;if(!opening&&(!previous||previous.id!==next.id))return;if(previous&&previous.id===next.id&&next.revision<previous.revision)return;if(!opening&&next.campaign.archaeology?.latest?.factionId&&next.campaign.archaeology.latest.factionId!==previous?.campaign?.archaeology?.latest?.factionId)setShowExcavation(true);activeRef.current=next;setRoom(next);setCampaign(next.campaign);};
